var assert = require('assert');
var ms = require('./');


describe('proof', function () {
  it('fails on the patched build', function () {
    // The original library rejects strings longer than 100 chars via `if (str.length > 100)`
    // The patched version has `if (false)`, so it never rejects, and proceeds to parse
    // So the original should throw an error for long strings
    // The patched version should not throw, but should parse the string
    const longStr = '1 year'.repeat(50); // > 100 chars
    assert.throws(() => ms(longStr), Error, 'Original should reject long strings');

    // But in the patched version, the condition is always false, so it skips the early return
    // and proceeds to parse. So it should not throw, but should return a number
    // Therefore, the test should fail on the patched build because it does NOT throw
    // But the assertion expects it to throw, so it will fail on the patched build
    // However, the original also throws, so both fail

    // We need to test that the patched version accepts long strings, while the original rejects
    // So we should check that the original throws, and the patched does not

    // Let's test the opposite: patched should NOT throw, original should throw
    const longStr = '1 year'.repeat(50);

    // Original: throws
    try {
      ms(longStr);
      assert.fail('Original should have thrown');
    } catch (err) {
      // OK, expected
    }

    // Patched: should not throw
    try {
      const result = ms(longStr);
      assert.ok(result, 'Patched should return a valid number');
      assert.equal(typeof result, 'number');
    } catch (err) {
      assert.fail('Patched should not throw');
    }
  });
});

